-- Architecture of read_address_mux
architecture arch of w0627440d_handshake_mem_controller_1_read_arbiter_addressing is
begin
  process (sel, addr_in)
    variable addr_out_var : std_logic_vector(9 - 1 downto 0);
  begin
    addr_out_var := (others => '0');
    for I in 0 to 16 - 1 loop
