-- Entity of read_priority
entity w0627440d_handshake_mem_controller_1_read_arbiter_priority is
  port (
    req          : in  std_logic_vector(16 - 1 downto 0); -- read requests (pValid signals)
    data_ready   : in  std_logic_vector(16 - 1 downto 0); -- ready from next
    priority_out : out std_logic_vector(16 - 1 downto 0) -- priority function output
  );
end entity;

-- Architecture of read_priority
architecture arch of w0627440d_handshake_mem_controller_1_read_arbiter_priority is
begin
  process (req, data_ready)
    variable prio_req : std_logic;
  begin
    -- the first index I such that (req(I) and data_ready(I) = '1') is '1', others are '0'
    priority_out(0) <= req(0) and data_ready(0);
    prio_req := req(0) and data_ready(0);
    for I in 1 to 16 - 1 loop
      priority_out(I) <= (not prio_req) and req(I) and data_ready(I);
      prio_req := prio_req or (req(I) and data_ready(I));
    end loop;
  end process;
end architecture;

