-- Entity of read_data_signals
entity w0627440d_handshake_mem_controller_1_read_arbiter_data is
  port (
    rst       : in  std_logic;
    clk       : in  std_logic;
    sel       : in  std_logic_vector(16 - 1 downto 0);
    read_data : in  std_logic_vector(64 - 1 downto 0);
    out_data  : out data_array(16 - 1 downto 0)(64 - 1 downto 0);
    valid     : out std_logic_vector(16 - 1 downto 0);
    nReady    : in  std_logic_vector(16 - 1 downto 0)
  );
end entity;

-- Architecture of read_data_signals
architecture arch of w0627440d_handshake_mem_controller_1_read_arbiter_data is
  signal sel_prev : std_logic_vector(16 - 1 downto 0);
  signal out_reg  : data_array(16 - 1 downto 0)(64 - 1 downto 0);
begin

  process (clk) is
  begin
    if (rising_edge(clk)) then
      if (rst = '1') then
        for I in 0 to 16 - 1 loop
          valid(I)    <= '0';
          sel_prev(I) <= '0';
        end loop;
      else
        for I in 0 to 16 - 1 loop
          sel_prev(I) <= sel(I);
          if (sel(I) = '1') then
            valid(I) <= '1'; --or not nReady(I); -- just sel(I) ??
            --sel_prev(I) <= '1';
          else
            if (nReady(I) = '1') then
              valid(I) <= '0';
              ---sel_prev(I) <= '0';
            end if;
          end if;
        end loop;
      end if;
    end if;
  end process;

  process (clk) is
  begin
    if (rising_edge(clk)) then
      if (rst = '1') then
        for I in 0 to 16 - 1 loop
          out_reg(I) <= (others => '0');
        end loop;
      else
        for I in 0 to 16 - 1 loop
          if (sel_prev(I) = '1') then
            out_reg(I) <= read_data;
          end if;
        end loop;
      end if;
    end if;
  end process;

  process (read_data, sel_prev, out_reg) is
  begin
    for I in 0 to 16 - 1 loop
      if (sel_prev(I) = '1') then
        out_data(I) <= read_data;
      else
        out_data(I) <= out_reg(I);
      end if;
    end loop;
  end process;

end architecture;

