-- Entity of read_memory_arbiter
entity w0627440d_handshake_mem_controller_1_read_arbiter is
  port (
    rst : in std_logic;
    clk : in std_logic;
    --- interface to previous
    pValid     : in  std_logic_vector(16 - 1 downto 0); -- read requests
    ready      : out std_logic_vector(16 - 1 downto 0); -- ready to process read
    address_in : in  data_array(16 - 1 downto 0)(9 - 1 downto 0);
    ---interface to next
    nReady   : in  std_logic_vector(16 - 1 downto 0); -- next component can accept data
    valid    : out std_logic_vector(16 - 1 downto 0); -- sending data to next component
    data_out : out data_array(16 - 1 downto 0)(64 - 1 downto 0); -- data to next components

    ---interface to memory
    read_enable      : out std_logic;
    read_address     : out std_logic_vector(9 - 1 downto 0);
    data_from_memory : in  std_logic_vector(64 - 1 downto 0));

end entity;

-- Architecture of read_memory_arbiter
architecture arch of w0627440d_handshake_mem_controller_1_read_arbiter is
  signal priorityOut : std_logic_vector(16 - 1 downto 0);

begin

  priority : entity work.w0627440d_handshake_mem_controller_1_read_arbiter_priority
    port map(
      req          => pValid,
      data_ready   => nReady,
      priority_out => priorityOut
    );

  addressing : entity work.w0627440d_handshake_mem_controller_1_read_arbiter_addressing
    port map(
      sel      => priorityOut,
      addr_in  => address_in,
      addr_out => read_address
    );

  addressReady : entity work.w0627440d_handshake_mem_controller_1_read_arbiter_addressReady
    port map(
      sel    => priorityOut,
      nReady => nReady,
      ready  => ready
    );

  data : entity work.w0627440d_handshake_mem_controller_1_read_arbiter_data
    port map(
      rst       => rst,
      clk       => clk,
      sel       => priorityOut,
      read_data => data_from_memory,
      out_data  => data_out,
      valid     => valid,
      nReady    => nReady
    );

  process (priorityOut) is
    variable read_en_var : std_logic;
  begin
    read_en_var := '0';
    for I in 0 to 16 - 1 loop
      read_en_var := read_en_var or priorityOut(I);
    end loop;
    read_enable <= read_en_var;
  end process;

end architecture;

